CREATE TABLE IF NOT EXISTS marketplace_listings (id TEXT PRIMARY KEY,seller_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price_cents INTEGER NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'RUB',category TEXT,condition TEXT,location TEXT,status TEXT NOT NULL DEFAULT 'available',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS listing_media (id TEXT PRIMARY KEY,listing_id TEXT NOT NULL REFERENCES marketplace_listings(id) ON DELETE CASCADE,media_url TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS listing_saves (listing_id TEXT NOT NULL REFERENCES marketplace_listings(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(listing_id,user_id));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY,organizer_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',starts_at TEXT NOT NULL,ends_at TEXT,location TEXT,online_url TEXT,cover_url TEXT,privacy TEXT NOT NULL DEFAULT 'public',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS event_attendees (event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'interested',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS event_posts (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS search_history (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,query TEXT NOT NULL,filters_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_marketplace_listings ON marketplace_listings(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_events_date ON events(starts_at);
